// ── §3 Diverging bar charts (built with HTML divs) ─────────────────
function buildDivBar(containerId, data, globalMedian) {
  const maxDev = Math.max(...data.map(d=>Math.abs(d.val-globalMedian)));
  const scale = 90; // px per maxDev
  let html = '';
  // Sort by deviation descending
  const sorted = [...data].sort((a,b)=>(b.val-globalMedian)-(a.val-globalMedian));
  sorted.forEach(item=>{
    const dev = item.val - globalMedian;
    const barPx = Math.abs(dev)/maxDev * scale;
    const sign  = dev >= 0 ? '+' : '−';
    const signedDev = Math.abs(dev).toFixed(0);
    html += `<div class="divbar-row">
      <div class="divbar-label">${item.label}</div>
      <div class="divbar-track">`;
    if(dev < 0){
      html += `<div style="flex:${scale-barPx};min-width:0"></div>
               <div class="divbar-neg" style="width:${barPx}px"></div>`;
    }
    html += `<div class="divbar-mid"></div>`;
    if(dev >= 0){
      html += `<div class="divbar-pos" style="width:${barPx}px"></div>
               <div style="flex:${scale-barPx};min-width:0"></div>`;
    }
    html += `</div>
      <div class="divbar-val">${sign}$${signedDev}</div>
    </div>`;
  });
  document.getElementById(containerId).innerHTML = html;
}

